def parse_input(text):
    lines = [
        line.strip()
        for line in text.splitlines()
        if line.strip()
    ]

    result = []
    i = 0

    while i < len(lines):
        predicate = lines[i]
        i += 1

        if i + 1 >= len(lines):
            raise ValueError(
                f"Missing generation or validation set for '{predicate}'"
            )

        generation_set = ast.literal_eval(lines[i])
        validation_set = ast.literal_eval(lines[i + 1])
        i += 2

        result.append({
            "predicate": predicate,
            "generation_set": sorted(
                [list(item) for item in generation_set]
            ),
            "validation_set": sorted(
                [list(item) for item in validation_set]
            ),
        })

    return result


def main():
    data = parse_input(INPUT)

    with open("predicate_sets.json", "w", encoding="utf-8") as file:
        json.dump(data, file, indent=2, ensure_ascii=False)

    print(f"Generated predicate_sets.json with {len(data)} predicates.")


if __name__ == "__main__":
    main()